"""Complete eight distinct mayonnaise and cream sauce formulas."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'dressing-candidates.json').read_text(encoding='utf-8'))

records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def oil(a):return I('oil',a,'ml','olive oil','Use the same volume of a mild sunflower or rapeseed oil.')
def vinegar(a,kind='white wine'):return I('vinegar',a,'ml',kind+' vinegar','Use the same volume of cider vinegar for a different flavor.')
def salt(a=.5):return I('salt',a,'tsp','fine salt','Reduce or omit to taste.')
def pepper(a=.25):return I('pepper',a,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def parsley(a=1):return I('parsley',a,'tsp','fresh parsley, finely chopped','Use the same amount of finely chopped chives.')
def tk(k):return '{{'+k+'}}'
STORE='Use promptly, or cover and refrigerate at 4°C (40°F) or colder for up to 3 days. Whisk again before serving; oil and vinegar naturally separate. This is a fresh dressing, not a shelf-stable preserve.'
NOTE=' Spoon measures use the app’s modern 15 ml tablespoon and 5 ml teaspoon. Yields, missing quantities and preparation times are modern estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes ingredient amounts, not preparation times.'
def add(n,title,y,t,desc,items,steps,notes):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category='Condiments',servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T20:00:00Z',notes=notes+NOTE,source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
def yolks(a):return I('yolks',a,'','large pasteurized egg yolks','Use 18 g commercially pasteurized liquid egg yolk per yolk; do not substitute unpasteurized raw egg.')
def mustard(a):return I('mustard',a,'tsp','dry mustard powder','Use the same volume of prepared Dijon mustard for a milder flavor.')
def cayenne():return I('cayenne',.0625,'tsp','ground cayenne pepper','Omit for a mild mayonnaise.')
def lemon(a):return I('lemon',a,'ml','lemon juice','Use the same volume of lime juice for a different flavor.')
COLD='Transfer to a clean covered container and refrigerate immediately at 4°C (40°F) or colder. Use within 3 days, using a clean spoon each time. This is fresh homemade mayonnaise, not a shelf-stable preserve.'
def emulsion(keys):
 return ['Set a clean small bowl on a damp towel to steady it. Whisk '+', '.join(tk(k) for k in keys)+' until smooth.','Measure {{oil}} into a jug. Whisk continuously while adding it drop by drop at first. Once the mixture is thick and glossy, add the remaining measured oil in a very thin stream, whisking until fully incorporated. Stop pouring if oil pools on the surface and whisk until it blends in.','The finished mayonnaise should be smooth and creamy. If it separates, put 1 teaspoon cold drinking water in a clean bowl and whisk the separated mixture into it a few drops at a time; this small repair addition changes the yield slightly.',COLD]
def eggsource(r):r['source']+=' Raw-yolk handling uses commercially pasteurized egg: https://www.foodsafety.gov/people-at-risk .';return r
def eggs(a):return I('eggs',a,'','large eggs for hard boiling','Use large pasteurized shell eggs if preferred; cook until the yolks are firm.')
def water(a,k='water'):return I(k,a,'ml','drinking water','Use the same volume of drinking water, topping up to cover as directed.')
def boil():return ['Put {{eggs}} in a saucepan with {{water}}, adding more water only if needed to cover by about 2 cm. Bring to a boil, cover, remove from heat and stand for 12 minutes. Cool under cold running water, peel and cut open; the yolks must be firm throughout.']
END='Keep covered at 4°C (40°F) or colder until serving. Refrigerate leftovers within 2 hours and use within 2 days. Do not leave the platter at room temperature for more than 2 hours.'
REF=' Cooking endpoints: https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures . Variety meats: https://ask.fsis.usda.gov/article/What-are-the-recommended-cooking-times-for-veal .'
def finish(r):r['category']='Main dishes';r['source']+=REF;return eggsource(r)

def preparedmustard(a):return I('mustard',a,'ml','prepared smooth mustard','Use the same volume of Dijon mustard; the flavor may be sharper.')
def whitepepper(a=.125):return I('whitepepper',a,'tsp','ground white pepper','Use the same amount of black pepper; the appearance changes.')
def cream(a,k='cream'):return I(k,a,'ml','pasteurized heavy cream','Use the same volume of unsweetened dairy-free cooking cream; texture and flavor differ.')

r=add(37,'Scandinavian Mustard Mayonnaise',12,15,'A smooth mustard mayonnaise is finished with vinegar and a small pinch of cayenne.',[yolks(2),preparedmustard(7.5),oil(180),vinegar(15),salt(.5),cayenne()],['Whisk {{yolks}} and {{mustard}} in a clean bowl. Gradually whisk in {{oil}}, beginning drop by drop and continuing in a thin stream once the sauce thickens. Stop pouring if oil pools and whisk until it blends in.','Slowly whisk in {{vinegar}}, {{salt}} and {{cayenne}} until smooth and evenly colored. Serve in small portions with already-cooked chilled lobster or fish, or green salad.',COLD],'The original scan reads one and a half Sennepske, meaning mustard spoons, not tablespoons. Their exact volume is unresolved; 7.5 ml prepared mustard is an explicit modern working amount, not a historical conversion. The source describes adding a small spoonful of oil gradually until thick without a reliable total; 180 ml is supplied. The half teaspoon salt and tablespoon vinegar are retained using modern spoon measures.');eggsource(r)

r=add(38,'Uægte Majonaise — Light Whipped Danish Dressing',16,60,'A cooled stock-and-butter sauce is enriched with yolks, lemon and oil, then lightened with whipped pasteurized egg whites.',[I('butter',30,'g','unsalted butter','Use the same weight of a block-style dairy-free butter alternative.'),I('flour',30,'g','plain flour','Use the same weight of a plain gluten-free flour blend suitable for sauces.'),I('stock',200,'ml','unsalted prepared chicken stock','Use the same volume of unsalted prepared vegetable stock.'),yolks(4),oil(100),preparedmustard(5),salt(.5),whitepepper(),lemon(45),I('whites',90,'g','pasteurized liquid egg whites labeled suitable for whipping','Use 90 g whites from commercially pasteurized shell eggs; do not use unpasteurized raw whites.')],['Melt {{butter}} in a saucepan over medium-low heat. Stir in {{flour}} for 2 minutes without browning. Gradually whisk in {{stock}} and simmer for 5 minutes, stirring, until thick and smooth.','Transfer the sauce to a shallow bowl over ice water. Stir frequently for about 20 minutes until cold, keeping water out of the sauce.','Beat {{yolks}} into the cold sauce in several additions. Gradually beat in {{oil}}, followed by {{mustard}}, {{salt}}, {{whitepepper}} and {{lemon}}. All eggs added after cooling must be commercially pasteurized.','In a separate clean, grease-free bowl, whip {{whites}} to soft peaks. Fold one third into the sauce to loosen it, then gently fold in the rest until no streaks remain. Serve promptly as a light dressing for already-cooked chilled foods.','Cover and refrigerate immediately at 4°C (40°F) or colder. Use the same day for the best texture; the foam gradually loses volume. Refrigerate within 2 hours, or within 1 hour above 32°C (90°F).'],'The original specifically cools the cooked flour-and-stock base before adding four yolks and three whipped whites. Commercially pasteurized eggs retain this uncooked enrichment without pretending that the roux cooking also cooks the eggs. Three whites are standardized to 90 g. Butter, flour, stock, oil, mustard, acid and seasoning quantities are modern additions. This is distinct from the cooked-yolk Forloren Mayonnaise.');eggsource(r)

r=add(46,'Dutch Mayonnaise — First Recipe',20,20,'A classic mustard-and-vinegar mayonnaise uses the source’s full 350 ml of oil, with a whole-egg variation.',[yolks(2),oil(350),vinegar(50),preparedmustard(7.5),salt(.5),whitepepper()],['Whisk {{yolks}}, {{mustard}}, {{salt}} and {{whitepepper}} in a clean bowl. Add {{vinegar|0.1}} and whisk until smooth.','Measure {{oil}} into a jug. Gradually whisk it in, drop by drop at first, then in a thin stream. Alternate the later oil additions with small additions of {{vinegar|0.9}} until all the measured ingredients are incorporated and the sauce is smooth.','Serve with already-cooked chilled meat, fish or vegetables. If the sauce separates, put one additional pasteurized yolk in a clean bowl and gradually whisk the broken sauce into it; this conditional rescue increases the yield.',COLD],'The original page clearly gives 3½ dl oil, equal to 350 ml, not the 150 ml that could be inferred from its OCR. The half deciliter vinegar is 50 ml. Two pasteurized yolks are chosen from the source’s one-whole-egg-or-two-yolks option. Modern seasoning and yield are supplied. Refrigeration replaces storage merely under an oil layer. Prepared mustard is chosen; the same 7.5 ml dry mustard powder is the source alternative and gives a stronger flavor.');eggsource(r)
vi=[I('wholeegg',50,'g','pasteurized liquid whole egg','Use one large commercially pasteurized shell egg, weighing about 50 g without its shell.') if i['key']=='yolks' else copy.deepcopy(i) for i in r['ingredients']];vs=[s.replace('{{yolks}}','{{wholeegg}}') for s in r['steps']];variant(r,'whole-egg','With one pasteurized whole egg',vi,vs)

r=add(47,'Dutch Mayonnaise — Cornstarch Version',16,40,'A cooked cornstarch base produces a lighter-oil mustard mayonnaise, finished after cooling with pasteurized yolks.',[water(150),I('cornstarch',10,'g','cornstarch','Use the same weight of potato starch; simmer only until thick because prolonged boiling can weaken it.'),vinegar(50),preparedmustard(7.5),salt(.5),whitepepper(),yolks(2),oil(100)],['Whisk {{cornstarch}} with {{water}} in a small saucepan until no lumps remain. Bring to a simmer while whisking, then cook for 3–4 minutes, stirring, until thickened.','Remove from heat and stir in {{vinegar}}, {{mustard}}, {{salt}} and {{whitepepper}}. Transfer to a shallow bowl over ice water and stir frequently for about 15–20 minutes until cold, keeping water out.','Beat {{yolks}} into the cold base. Gradually beat in {{oil}}, drop by drop at first, until the sauce is smooth and creamy. Use commercially pasteurized yolks because they are added after cooling.',COLD],'The source’s 150 ml water, 10 g cornstarch, 50 ml vinegar, two yolks, 100 ml oil and 1½ teaspoons mustard are retained. Seasoning, cooling time and yield are modern additions. Cooking the starch does not cook the yolks subsequently added. Prepared mustard is chosen; the source also permits the same volume of mustard powder for a stronger flavor.');eggsource(r)

r=add(49,'Warme Mayonnaise — Dutch Warm Cream Sauce',6,20,'A warm, tangy egg sauce combines cooking cream and oil over gentle steam, with vinegar added off the heat.',[I('yolks',3,'','large egg yolks','Use 18 g pasteurized liquid egg yolk per yolk; the sauce is still cooked.'),I('cream',50,'ml','pasteurized cooking cream','Use the same volume of heavy cream for a richer sauce.'),oil(50),vinegar(50),preparedmustard(5),salt(.25),whitepepper(.0625)],['Bring a little water to a gentle simmer in a saucepan. In a heatproof bowl that fits over it without touching the water, whisk {{yolks}}, {{salt}}, {{whitepepper}} and {{mustard}}. Gradually whisk in {{oil}} and {{cream}}.','Set the bowl over the simmering water and whisk constantly for about 5–8 minutes until the sauce lightly thickens and reaches 71°C (160°F) throughout. Lift the bowl away from the steam if it heats too quickly; do not let the sauce boil.','Remove the bowl from the heat. Slowly whisk in {{vinegar}}, a few drops at a time at first, until evenly blended. Serve immediately with already-cooked warm salmon or other cooked fish.','This delicate warm sauce is best freshly made. Refrigerate leftovers in a shallow covered container within 2 hours, or within 1 hour above 32°C (90°F), and use within 2 days as a cold dressing; reheating may split it.'],'The original gives three yolks and 50 ml each of cream, oil and vinegar. These proportions are retained rather than silently reducing the acid. Mustard, seasoning and a measured egg-cooking endpoint are supplied. The vinegar is added gradually off the heat as the source specifies. Salmon is a serving suggestion; this entry is the sauce recipe.');r['source']+=REF

r=add(50,'Culinary Jottings Mayonnaise with Shallot',16,45,'Cooked and pasteurized yolks make a thick mustard mayonnaise with a restrained tarragon-vinegar finish; straining removes the shallot pieces.',[eggs(2),water(1000),salt(.25),I('mustard',10,'ml','dry mustard powder','Use the same volume of prepared English mustard for a milder version.'),I('shallot',5,'ml','very finely minced peeled shallot','Use the same volume of finely minced mild onion.'),whitepepper(.125),oil(250),yolks(2),vinegar(15,'tarragon')],boil()+['Separate the cooked yolks and reserve the whites for another dish. Mash the cooked yolks with {{salt}}, {{mustard}}, {{shallot}} and {{whitepepper}} until fine. Work in {{oil|0.1}} a few drops at a time to make a moist paste.','Beat in {{yolks}}, then gradually whisk in {{oil|0.9}}, a few drops at a time at first. Slowly whisk in {{vinegar}}. Push through a fine sieve into a clean bowl, discarding the coarse shallot and egg particles.','Refrigerate for at least 10 minutes before serving in small portions with already-cooked chilled foods.',COLD],'The source gives two cooked and two uncooked yolks and explicitly leaves the total oil unmeasured. A modern 250 ml working amount is supplied. Its salt spoon becomes an explicit modern ¼ teaspoon choice, not a verified historical conversion; the dessert spoon is represented by a modern 10 ml measure. The small tarragon-vinegar finish and straining are retained. Full cream-replacement and small cream-addition options preserve the source’s following sentences.');eggsource(r)
vi=[cream(250,'replacementcream') if i['key']=='oil' else copy.deepcopy(i) for i in r['ingredients']];vs=[s.replace('{{oil|0.1}}','{{replacementcream|0.1}}').replace('{{oil|0.9}}','{{replacementcream|0.9}}') for s in r['steps']];variant(r,'cream-instead-of-oil','Cream dressing without oil',vi,vs)
vi=copy.deepcopy(r['ingredients'])+[cream(10,'extracream')];vs=copy.deepcopy(r['steps']);vs[2]=vs[2].replace('Push through a fine sieve','Whisk in {{extracream}}. Push through a fine sieve');variant(r,'cream-enriched','With a little added cream',vi,vs);r['notes']+=' The all-cream version uses a supplied modern 250 ml and will be softer than the oil emulsion. The small addition uses 10 ml cream.'

r=add(55,'Greenbaum Mayonnaise Dressing',12,20,'A one-yolk olive-oil mayonnaise is seasoned with English mustard, cayenne and a small amount of vinegar or lemon.',[yolks(1),salt(.5),cayenne(),I('mustard',.5,'tsp','English mustard powder','Use the same volume of prepared English mustard for a milder flavor.'),oil(240),vinegar(10)],['Whisk {{yolks}}, {{salt}}, {{cayenne}} and {{mustard}} in a clean cool bowl. In a hot kitchen, set the bowl over another bowl of ice water, keeping water out of the sauce.','Measure {{oil}} into a jug and whisk it in drop by drop at first. Once the sauce thickens, alternate the later oil additions with small additions of {{vinegar}} until all is incorporated. Keep whisking until smooth.','If the sauce splits, beat one additional commercially pasteurized whole egg in a clean bowl and gradually whisk the broken mixture into it, drop by drop at first. This conditional repair increases the yield. The direction of whisking does not determine whether an emulsion succeeds.',COLD],'The source cup of oil is standardized to a modern 240 ml cup, with its two teaspoons acid, half teaspoon salt and half teaspoon English mustard retained. Cayenne is a measured small pinch. Twelve small condiment servings are estimated; the source separately suggests a pint of dressing for twenty people. Pasteurized yolk and a pasteurized whole egg for conditional rescue replace uncooked unpasteurized eggs.');eggsource(r)
vi=[lemon(10) if i['key']=='vinegar' else copy.deepcopy(i) for i in r['ingredients']];vs=[s.replace('{{vinegar}}','{{lemon}}') for s in r['steps']];variant(r,'lemon','Lemon mayonnaise',vi,vs)

r=add(56,'Cream and Cooked-Yolk Mayonnaise for Salmon',8,30,'Sieved cooked yolks enrich a cream dressing seasoned with white pepper, a trace of cayenne and a slow addition of white vinegar.',[eggs(2),water(1000),cream(120),whitepepper(.0625),salt(.125),cayenne(),vinegar(30,'white')],boil()+['Separate the cooked yolks and refrigerate the whites for another dish. Press the cooked yolks through a fine sieve into a clean bowl. Beat in {{cream}} very gradually until smooth.','Stir in {{whitepepper}}, {{salt}} and {{cayenne}}. Add {{vinegar}} very slowly, drop by drop at first, while stirring continuously; rapid acid addition can make the dressing grainy.','Chill for 10 minutes, then serve in small portions with already-cooked salmon. This is a cream dressing and contains no added oil.','Cover and refrigerate at 4°C (40°F) or colder. Use within 2 days. Refrigerate within 2 hours of preparation, or within 1 hour above 32°C (90°F).'],'The eight tablespoons cream and two tablespoons vinegar become 120 ml and 30 ml using modern spoons. Both yolks are fully cooked as specified; the full boiling method is supplied. Heavy cream is a modern choice to provide a rich texture. Pepper, salt, cayenne, timing and eight condiment portions are modern estimates. Salmon is the source’s serving suggestion, not an omitted main-dish component.')

assert len(newids)==8,len(newids)
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
for id in newids:db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,records[id]['bodySha256'],'prepared-adaptation','Full sauce formulas and meaningful variants completed; original measurements checked','repair-batch-028.py'))
db.commit();print(json.dumps(dict(newAdaptations=len(newids),newMergedSources=0,totalOverrides=len(records),totalAliases=len(aliases))))

